class Node:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def build(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head

def print_list(head):
    out = []
    while head:
        out.append(str(head.val))
        head = head.next
    print(" ".join(out) if out else "-")

def reverse(head):
    prev = None
    while head:
        nxt = head.next      # remember the rest before rewiring
        head.next = prev     # point this node backwards
        prev = head
        head = nxt
    return prev

input()
print_list(reverse(build(list(map(int, input().split())))))

