#include <bits/stdc++.h>
using namespace std;
struct Node {
    long long val;
    Node* next;
    Node(long long v, Node* n = nullptr) : val(v), next(n) {}
};
Node* build(const vector<long long>& values) {
    Node* head = nullptr;
    for (int i = (int)values.size() - 1; i >= 0; i--) head = new Node(values[i], head);
    return head;
}
void printList(Node* head) {
    if (!head) { cout << "-\n"; return; }
    for (Node* p = head; p; p = p->next) cout << p->val << (p->next ? " " : "\n");
}
Node* reverseList(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;  // remember the rest before rewiring
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}
int main() {
    int n;
    cin >> n;
    vector<long long> v(n);
    for (auto& x : v) cin >> x;
    printList(reverseList(build(v)));
    return 0;
}

