#include <bits/stdc++.h>
using namespace std;
int n;
vector<int> nxt;
int step(int i) { return i == -1 ? -1 : nxt[i]; }
int main() {
    cin >> n;
    nxt.resize(n);
    for (auto& x : nxt) cin >> x;
    int slow = 0, fast = 0;
    while (true) {
        slow = step(slow);
        fast = step(step(fast));
        if (fast == -1 || slow == -1) { cout << -1 << "\n"; return 0; }
        if (slow == fast) break;
    }
    slow = 0;  // both now move one step: they meet at the cycle's start
    while (slow != fast) { slow = nxt[slow]; fast = nxt[fast]; }
    cout << slow << "\n";
    return 0;
}

