struct Node {
    long long val;
    Node* next;
    Node(long long v, Node* n = nullptr) : val(v), next(n) {}
};
Node* build(const vector<long long>& values) {
    Node* head = nullptr;
    for (int i = (int)values.size() - 1; i >= 0; i--) head = new Node(values[i], head);
    return head;
}
void printList(Node* head) {
    if (!head) { cout << "-\n"; return; }
    for (Node* p = head; p; p = p->next) cout << p->val << (p->next ? " " : "\n");
}
int main() {
    int n, k;
    cin >> n;
    vector<long long> v(n);
    for (auto& x : v) cin >> x;
    cin >> k;
    Node dummy(0, build(v));
    Node* groupPrev = &dummy;
    while (true) {
        Node* kth = groupPrev;
        for (int i = 0; i < k && kth; i++) kth = kth->next;
        if (!kth) break;                       // fewer than k nodes left
        Node* groupNext = kth->next;
        Node* prev = groupNext;
        Node* cur = groupPrev->next;
        while (cur != groupNext) {
            Node* nxt = cur->next;
            cur->next = prev;
            prev = cur;
            cur = nxt;
        }
        Node* first = groupPrev->next;          // now the group's last node
        groupPrev->next = kth;
        groupPrev = first;
    }
    printList(dummy.next);
    return 0;
}

